import sys
import traceback


def _test(expected, actual, call):
    try:
        assert actual == expected, "{} should return {}. Your code: {}".format(call, expected, actual)
        print("\u2713 passed: {} \u2192 {}".format(call, expected))
    except AssertionError as ae:
        print("\u2717 failed: {}".format(ae))


class LLTests:

    def __init__(self, module_name):
        self.module = module_name

    # ---------- Node tests ----------

    def test_01_node_basic(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            n = self.module.Node(10)
            _test(
                expected=10,
                actual=n.data,
                call="Node(10).data"
            )
            _test(
                expected=None,
                actual=n.next,
                call="Node(10).next"
            )
            _test(
                expected="Node(data=10)",
                actual=str(n),
                call="str(Node(10))"
            )
        except Exception as e:
            print("\u2717 FAILED. Node basic test raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

