    def test_08_remove_head_tail_middle(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            ll = self.module.LinkedList()
            for x in ["A", "B", "C", "D"]:
                ll.append(x)         # A -> B -> C -> D

            # remove head
            ll.remove("A")           # B -> C -> D
            _test(
                expected="B",
                actual=ll.head.data,
                call="head after removing head"
            )

            # remove middle
            ll.remove("C")           # B -> D
            data_mid = [node.data for node in ll]
            _test(
                expected=["B", "D"],
                actual=data_mid,
                call="list after removing middle element"
            )

            # remove tail
            ll.remove("D")           # B
            _test(
                expected="B",
                actual=ll.tail.data,
                call="tail after removing tail"
            )
            _test(
                expected=1,
                actual=ll.size,
                call="size after three removes"
            )
        except Exception as e:
            print("\u2717 FAILED. remove head/middle/tail test raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_09_remove_only_element_and_missing(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            # remove only element
            ll = self.module.LinkedList()
            ll.append("X")
            ll.remove("X")
            _test(
                expected=None,
                actual=ll.head,
                call="head after removing only element"
            )
            _test(
                expected=None,
                actual=ll.tail,
                call="tail after removing only element"
            )
            _test(
                expected=0,
                actual=ll.size,
                call="size after removing only element"
            )

            # removing from list where item not present
            ll2 = self.module.LinkedList()
            ll2.append("A")
            raised = False
            try:
                ll2.remove("Z")
            except ValueError:
                raised = True
            _test(
                expected=True,
                actual=raised,
                call="remove(item not in list) should raise ValueError"
            )
        except Exception as e:
            print("\u2717 FAILED. remove-only/missing test raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_10_pop_default_and_indices(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            ll = self.module.LinkedList()
            for x in [1, 2, 3, 4]:
                ll.append(x)          # 1,2,3,4

            # default pop: should remove and return tail (4)
            val = ll.pop()
            _test(
                expected=4,
                actual=val,
                call="pop() on [1,2,3,4]"
            )
            _test(
                expected=3,
                actual=ll.tail.data,
                call="tail after pop()"
            )
            _test(
                expected=3,
                actual=ll.size,
                call="size after pop()"
            )

            # pop head with index 0
            val0 = ll.pop(0)
            _test(
                expected=1,
                actual=val0,
                call="pop(0) on [1,2,3]"
            )
            _test(
                expected=2,
                actual=ll.head.data,
                call="head after pop(0)"
            )
            _test(
                expected=2,
                actual=ll.size,
                call="size after pop(0)"
            )

            # pop remaining last element by index
            val_last = ll.pop(1)      # list is [2,3]; index 1 -> 3
            _test(
                expected=3,
                actual=val_last,
                call="pop(1) on [2,3]"
            )
            _test(
                expected=1,
                actual=ll.size,
                call="size after popping last element by index"
            )
            _test(
                expected=2,
                actual=ll.head.data,
                call="head after popping last element by index"
            )
            _test(
                expected=2,
                actual=ll.tail.data,
                call="tail after popping last element by index"
            )
        except Exception as e:
            print("\u2717 FAILED. pop default/index test raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_11_pop_errors_and_types(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            # pop from empty list -> IndexError
            ll_empty = self.module.LinkedList()
            raised_index = False
            try:
                ll_empty.pop()
            except IndexError:
                raised_index = True
            _test(
                expected=True,
                actual=raised_index,
                call="pop() on empty list should raise IndexError"
            )

            # pop with bad type -> TypeError
            ll = self.module.LinkedList()
            ll.append(1)
            raised_type = False
            try:
                ll.pop("abc")
            except TypeError:
                raised_type = True
            _test(
                expected=True,
                actual=raised_type,
                call="pop('abc') should raise TypeError"
            )

            # pop with out-of-range index -> IndexError
            ll2 = self.module.LinkedList()
            ll2.append(1)
            ll2.append(2)
            raised_index_oor = False
            try:
                ll2.pop(5)
            except IndexError:
                raised_index_oor = True
            _test(
                expected=True,
                actual=raised_index_oor,
                call="pop(5) out of range should raise IndexError"
            )
        except Exception as e:
            print("\u2717 FAILED. pop error tests raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())


    def test_all(self):
        self.test_01_node_basic()
        self.test_02_ll_init_is_empty()
        self.test_03_add_basic()
        self.test_04_append_basic()
        self.test_05_append_to_empty()
        self.test_06_iter_basic()
        self.test_07_search()
        self.test_08_remove_head_tail_middle()
        self.test_09_remove_only_element_and_missing()
        self.test_10_pop_default_and_indices()
        self.test_11_pop_errors_and_types()











